def python_imports(tree):
    """Имена модуля `os` и функции, ввезённые `from os/shutil import …` (rmtree, remove, …)."""
    os_names = {"os"}
    funcs = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                if a.name == "os":
                    os_names.add(a.asname or "os")
        elif isinstance(node, ast.ImportFrom) and node.module in ("os", "shutil"):
            for a in node.names:
