    if sub == "stash":
        pos = [a for a in rest if not a.startswith("-")]
        return f"git stash {pos[0]}" if pos and pos[0] in ("clear", "drop") else None
    if sub == "checkout":
        return checkout_discard(rest, short, long_, ctx, repo)
